 "content": "from collections import Counter

def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(n):
        for c in range(m):
            orbit = {(r, c), (r, m - 1 - c), (n - 1 - r, c), (n - 1 - r, m - 1 - c)}
            if orbit in seen:
                continue
            seen.add(frozenset(orbit))
            vals = [grid[i][j] for i, j in orbit if grid[i][j] != 3]
            if vals:
                counts = Counter(vals)
                value = counts.most_common(1)[0][0]
            else:
                value = 3
            for i, j in orbit:
                out[i][j] = value
    return out
